/// <summary>
/// WolfA 16.04.21
/// </summary>
class NDXUSCImportBatchJob extends RunBaseBatch
{
    SysGlobalobjectCache sgoc;
}

Method.Source:
public void run()
{
    boolean isUSCImporting;
    [isUSCImporting] = sgoc.find(DMFConstants::DataPopulationGlobalCacheScope, ['USCImportKey']);

    if (!isUSCImporting)
    {
        NDXUSCCheck ndxUSCCheck = new NDXUSCCheck();
        sgoc.insert(DMFConstants::DataPopulationGlobalCacheScope, ['USCImportKey'], [true]);
        try
        {
            ndxUSCCheck.run();
            Info('USC Import Succesful');
        }
        catch
        {
            Info('USC Import Error');
        }
        sgoc.remove(DMFConstants::DataPopulationGlobalCacheScope, ['USCImportKey']);
    }
}

private static ClassDescription description()
{
    return 'Online Check USt-Id';
}

public static void main(Args _args)
{
    NDXUSCImportBatchJob lNDXUSCImportBatchJob = new NDXUSCImportBatchJob();
    lNDXUSCImportBatchJob.runOperation();
}
